import { z } from 'zod';

/**
 * Chat of a consultation. Messages are sent over REST (idempotent through
 * `clientMsgId`) and pushed to the other side over Socket.io
 * (see realtime.contract). Bodies and attachments are encrypted at rest.
 */
export type MessageType = 'TEXT' | 'IMAGE' | 'SYSTEM' | 'PRESCRIPTION';
export type ChatRole = 'PATIENT' | 'PROVIDER';

export interface ChatAttachment {
  mimeType: string;
  url: string;
  thumbnailUrl: string | null;
  previewUrl: string | null;
}

export interface MessageResponse {
  id: string;
  conversationId: string;
  /** null for SYSTEM messages. */
  senderId: string | null;
  senderRole: ChatRole | 'SYSTEM';
  type: MessageType;
  body: string | null;
  attachment: ChatAttachment | null;
  /** PRESCRIPTION: the prescription id (open it from the chat). */
  refId: string | null;
  /** Echo of the sender's id, so the sender can match its optimistic copy. */
  clientMsgId: string | null;
  createdAt: string;
}

export interface ChatParticipantResponse {
  userId: string;
  role: ChatRole;
  lastReadAt: string | null;
}

/** GET /api/v1/conversations/:conversationId */
export interface ConversationResponse {
  id: string;
  consultationId: string;
  /** False once the consult ended: read only. */
  isOpen: boolean;
  myRole: ChatRole;
  participants: ChatParticipantResponse[];
  unreadCount: number;
  lastMessageAt: string | null;
  /** Attachment URLs in messages fetched now stop working at this time. */
  urlsExpireAt: string;
}

// GET /api/v1/conversations/:conversationId/messages — newest first.
export const listMessagesQuerySchema = z.object({
  cursor: z.string().min(1).max(512).optional(),
  limit: z.coerce.number().int().min(1).max(100).default(30),
});
export type ListMessagesQuery = z.infer<typeof listMessagesQuerySchema>;

// POST /api/v1/conversations/:conversationId/messages
export const sendMessageRequestSchema = z.object({
  /** Generated by the client; sending the same one again returns the first message. */
  clientMsgId: z.uuid(),
  body: z.string().trim().min(1).max(2000),
});
export type SendMessageRequest = z.infer<typeof sendMessageRequestSchema>;

// POST /api/v1/conversations/:conversationId/images (multipart: file + these fields)
export const sendImageFieldsSchema = z.object({
  clientMsgId: z.uuid(),
  caption: z.string().trim().max(500).optional(),
});
export type SendImageFields = z.infer<typeof sendImageFieldsSchema>;
